begin;
select plan(32);
select ok(not has_table_privilege('anon','public.currency_report_runs','SELECT'),'anon cannot read private runs');
select ok(not has_table_privilege('authenticated','public.currency_report_runs','INSERT'),'authenticated cannot insert drafts');
select ok(not has_table_privilege('service_role','public.currency_report_reviews','UPDATE'),'service cannot mutate review history');
select ok(not has_table_privilege('service_role','public.currency_report_reviews','INSERT'),'service cannot impersonate admin review');
select ok(not has_table_privilege('service_role','public.currency_reports','INSERT'),'service cannot bypass initial manual publication');
select ok(not has_function_privilege('anon','public.review_currency_report(uuid,text,text)','EXECUTE'),'anon cannot review');
insert into public.business_plan_admins(email,active) values('currency-admin@example.test',true);
insert into public.currency_report_runs(id,currency,base_date,attempt,rule_version,event_binding,packet,candidate,validation)
 values('30000000-0000-0000-0000-000000000001','BRL','2099-01-01',1,'test','binding','{}','{}','{}');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000010","email":"reader@example.test","role":"authenticated"}',true);
select is((select count(*) from public.currency_report_runs),0::bigint,'non-admin reads no drafts');
select throws_ok($$select public.review_currency_report('30000000-0000-0000-0000-000000000001','rejected',null)$$,'42501','active administrator access required','non-admin cannot reject');
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000011","email":"currency-admin@example.test","role":"authenticated"}',true);
select is((select count(*) from public.currency_report_runs where id='30000000-0000-0000-0000-000000000001'),1::bigint,'active admin reads draft');
select throws_ok($$select public.review_currency_report('30000000-0000-0000-0000-000000000001','approved',null)$$,'22023','content validation required','unreviewed draft cannot publish');
select lives_ok($$select public.review_currency_report('30000000-0000-0000-0000-000000000001','rejected','insufficient evidence')$$,'admin rejection is transactional');
select throws_ok($$select public.review_currency_report('30000000-0000-0000-0000-000000000001','rejected',null)$$,'55000','report run is no longer reviewable','duplicate rejection blocked');
reset role;
update public.business_plan_admins set active=false where email='currency-admin@example.test';
set local role authenticated;
select is((select count(*) from public.currency_report_runs),0::bigint,'revoked admin loses draft access with same JWT');
select throws_ok($$select public.review_currency_report('30000000-0000-0000-0000-000000000001','rejected',null)$$,'42501','active administrator access required','revoked admin cannot review');
reset role;
set local role service_role;
select lives_ok($$insert into public.currency_report_runs(id,currency,base_date,attempt,rule_version,event_binding,packet,candidate,validation) values('30000000-0000-0000-0000-000000000003','MXN','2099-01-01',1,'test','binding','{}','{}','{}')$$,'service role can append a generation attempt');
reset role;
update public.business_plan_admins set active=true where email='currency-admin@example.test';
insert into public.currency_report_runs(id,currency,base_date,attempt,rule_version,event_binding,packet,candidate,validation)
 values('30000000-0000-0000-0000-000000000002','BRL','2099-01-01',2,'test','binding',
 '{"raw":"SECRET_ORIGINAL"}',
 '{"id":"BRL-2099-01-01-2","schemaVersion":"currency-report/1","currency":"BRL","baseDate":"2099-01-01","observedDate":"2099-01-01","generationMode":"ai_enhanced","raw_ai_response":"SECRET_RESPONSE","content":{"title":"검토용 원고","summary":"검토용 요약","change":{"title":"변화","text":"계산된 값","kind":"fact","factIds":["spot"],"evidenceIds":[]},"drivers":[{"title":"배경","text":"출처에 귀속한 배경","kind":"interpretation","factIds":[],"evidenceIds":["e1"]}],"implications":[],"watch":[],"limitations":["합성 권한 시험"]},"facts":[{"id":"spot","value":1,"label":"1 USD = 1 BRL"}],"series":[{"date":"2099-01-01","value":1}],"evidence":[{"id":"e1","country":"BRL","title":"공식 시험","publisher":"공식 시험","url":"https://www.bcb.gov.br/","publishedAt":"2099-01-01T00:00:00Z","eventDate":"2099-01-01","period":"2099-01","collectedAt":"2099-01-01T00:00:00Z","summary":"합성 출처","sourceContext":{"body":"SECRET_ORIGINAL"}}],"limitations":["합성 권한 시험"]}',
 '{"structureValid":true,"contentReview":"passed","criticalErrors":0,"qualityAverage":4,"evidenceScore":4}');
update public.currency_report_runs set candidate=candidate || '{"presentationVersion":"monthly-facts/1","authorship":"ai_with_manual_edit","comparison":{"historicalReview":true,"secret":"SECRET_EDITORIAL"}}'::jsonb where id='30000000-0000-0000-0000-000000000002';
set local role authenticated;
select lives_ok($$select public.review_currency_report('30000000-0000-0000-0000-000000000002','approved',null)$$,'valid admin approval publishes sanitized snapshot');
select is((select report->>'authorship' from public.currency_reports where run_id='30000000-0000-0000-0000-000000000002'),'ai_with_manual_edit','manual authorship survives atomic public projection');
select is((select report->>'presentationVersion' from public.currency_reports where run_id='30000000-0000-0000-0000-000000000002'),'monthly-facts/1','allowlisted display version survives approval');
select is((select report->>'historicalReview' from public.currency_reports where run_id='30000000-0000-0000-0000-000000000002'),'true','historical reconstruction label survives projection');
select ok((select not (report ? 'comparison') from public.currency_reports where run_id='30000000-0000-0000-0000-000000000002'),'private editorial comparison not copied');
select throws_ok($$select public.review_currency_report('30000000-0000-0000-0000-000000000002','approved',null)$$,'55000','report run is no longer reviewable','duplicate approval blocked');
select ok((select report::text not like '%SECRET_%' from public.currency_reports where run_id='30000000-0000-0000-0000-000000000002'),'public copy omits raw response and original contexts');
reset role;
update public.currency_report_runs set candidate=jsonb_set(candidate,'{authorship}','"SECRET_EMAIL@example.test"') where id='30000000-0000-0000-0000-000000000002';
update public.currency_reports set report=report where run_id='30000000-0000-0000-0000-000000000002';
select ok((select not (report ? 'authorship') from public.currency_reports where run_id='30000000-0000-0000-0000-000000000002'),'unknown authorship cannot leak arbitrary text');
update public.currency_report_runs set candidate=jsonb_set(candidate,'{presentationVersion}','"PRIVATE@example.test"') where id='30000000-0000-0000-0000-000000000002';
update public.currency_reports set report=report where run_id='30000000-0000-0000-0000-000000000002';
select ok((select not (report ? 'presentationVersion') from public.currency_reports where run_id='30000000-0000-0000-0000-000000000002'),'unknown display version cannot expose arbitrary text');
update public.currency_report_runs set candidate=candidate-'presentationVersion' where id='30000000-0000-0000-0000-000000000002';
update public.currency_reports set report=report || '{"presentationVersion":"monthly-facts/1"}'::jsonb where run_id='30000000-0000-0000-0000-000000000002';
select ok((select not (report ? 'presentationVersion') from public.currency_reports where run_id='30000000-0000-0000-0000-000000000002'),'legacy candidate cannot acquire display opt-in from public copy');
set local role anon;
select is((select count(*) from public.currency_reports where base_date='2099-01-01'),1::bigint,'anon reads one approved report');
select ok(not has_table_privilege(current_user,'public.currency_reports','UPDATE'),'anon cannot alter public report');
reset role;
set local role authenticated;
select throws_ok($$select public.review_currency_report('30000000-0000-0000-0000-000000000002','withdrawn',null)$$,'22023','withdrawal reason required','withdrawal requires reason');
select lives_ok($$select public.review_currency_report('30000000-0000-0000-0000-000000000002','withdrawn','verified correction')$$,'admin withdraws without deleting report');
reset role;
set local role anon;
select is((select count(*) from public.currency_reports where base_date='2099-01-01'),0::bigint,'withdrawn report is no longer public');
reset role;
select is((select count(*) from public.currency_report_reviews where run_id in ('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002')),3::bigint,'rejection approval and withdrawal remain in audit history');
select ok((select packet->>'raw'='SECRET_ORIGINAL' from public.currency_report_runs where id='30000000-0000-0000-0000-000000000002'),'withdrawal preserves private original');
select * from finish();
rollback;
